/**
 * Email-Triggered Incident and Task Creation Flow
 *
 * This flow processes inbound emails with subject containing "raise incident or task":
 *
 * Flow Logic:
 * 1. Triggers when email subject contains "raise incident or task"
 * 2. Checks if sender is internal (servicenow domain)
 * 3. If internal AND subject contains "P1":
 *    - Creates 2 P1 incident tasks:
 *      a) Task for sender's manager with short_description = email body
 *      b) Task for sender with short_description = email subject
 * 4. Otherwise:
 *    - Creates a P3 incident with email information
 *
 * Tables Used:
 * - sys_email (inbound email)
 * - sys_user (sender lookup)
 * - incident (P3 incident creation)
 * - incident_task (P1 task creation)
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const emailTriggeredIncidentTaskFlow = Flow(
    {
        $id: Now.ID['email_triggered_incident_task_flow'],
        name: 'Email-Triggered Incident and Task Creation Flow',
        description: 'Processes emails to create P1 tasks or P3 incidents based on sender type and priority',
    },
    wfa.trigger(
        trigger.application.inboundEmail,
        { $id: Now.ID['email_trigger_raise_incident_or_task'] },
        {
            email_conditions: 'subjectLIKEraise incident or task',
            target_table: 'incident',
            order: 100,
        }
    ),
    (params) => {
        // Step 1: Log the received email
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['log_email_received_001'],
                annotation: 'Log email receipt',
            },
            {
                log_level: 'info',
                log_message: `Email received from: ${wfa.dataPill(params.trigger.from_address, 'string')}, Subject: ${wfa.dataPill(params.trigger.subject, 'string')}`,
            }
        )

        // Step 2: Check if sender is internal (contains servicenow domain)
        wfa.flowLogic.if(
            {
                condition: `${wfa.dataPill(params.trigger.from_address, 'string')}LIKEservicenow`,
                annotation: 'Check if sender is from ServiceNow (internal)',
                $id: Now.ID['check_internal_sender'],
            },
            () => {
                // Step 3: Check if email subject contains P1
                wfa.flowLogic.if(
                    {
                        condition: `${wfa.dataPill(params.trigger.subject, 'string')}LIKEP1`,
                        annotation: 'Check if email subject contains P1',
                        $id: Now.ID['check_p1_priority'],
                    },
                    () => {
                        // Internal sender + P1 request: Create 2 P1 incident tasks
                        wfa.action(
                            action.core.log,
                            {
                                $id: Now.ID['log_p1_internal_processing'],
                                annotation: 'Log P1 internal email processing',
                            },
                            {
                                log_level: 'info',
                                log_message: `Processing internal P1 request from: ${wfa.dataPill(params.trigger.from_address, 'string')}`,
                            }
                        )

                        // Step 4: Look up sender user record
                        const sender = wfa.action(
                            action.core.lookUpRecord,
                            {
                                $id: Now.ID['lookup_sender_user'],
                                annotation: 'Retrieve sender user record',
                            },
                            {
                                table: 'sys_user',
                                conditions: `email=${wfa.dataPill(params.trigger.from_address, 'string')}`,
                            }
                        )

                        // Step 5: Look up sender's manager
                        const senderManager = wfa.action(
                            action.core.lookUpRecord,
                            {
                                $id: Now.ID['lookup_sender_manager_001'],
                                annotation: 'Retrieve sender manager record',
                            },
                            {
                                table: 'sys_user',
                                conditions: `sys_id=${wfa.dataPill(sender.Record.manager, 'reference')}`,
                            }
                        )

                        // Step 7: Create P1 incident task for sender's manager (short_description = email body)
                        const managerTask = wfa.action(
                            action.core.createRecord,
                            {
                                $id: Now.ID['create_manager_p1_task'],
                                annotation: 'Create P1 task for sender manager with body as short description',
                            },
                            {
                                table_name: 'incident_task',
                                values: TemplateValue({
                                    short_description: 'Short Description P1',
                                    priority: 1,
                                    state: 1,
                                    assigned_to: `${wfa.dataPill(senderManager.Record.sys_id, 'reference')}`,
                                    description: `P1 Task created from email. Sender: ${wfa.dataPill(sender.Record.name, 'string')}. Email subject: P1 subject`,
                                }),
                            }
                        )

                        // Step 8: Create P1 incident task for sender (short_description = email subject)
                        const senderTask = wfa.action(
                            action.core.createRecord,
                            {
                                $id: Now.ID['create_sender_p1_task'],
                                annotation: 'Create P1 task for sender with subject as short description',
                            },
                            {
                                table_name: 'incident_task',
                                values: TemplateValue({
                                    short_description: 'Short Description P2',
                                    priority: 1,
                                    state: 1,
                                    assigned_to: `${wfa.dataPill(sender.Record.sys_id, 'reference')}`,
                                    description: `P1 Task created from email. Email body: Subject P2`,
                                }),
                            }
                        )

                        // Step 9: Log successful P1 task creation
                        wfa.action(
                            action.core.log,
                            {
                                $id: Now.ID['log_p1_tasks_created'],
                                annotation: 'Log successful P1 task creation',
                            },
                            {
                                log_level: 'info',
                                log_message: `P1 tasks created - Manager task: ${wfa.dataPill(managerTask.record, 'reference')}, Sender task: ${wfa.dataPill(senderTask.record, 'reference')}`,
                            }
                        )

                        // Step 10: Send confirmation notification to sender
                        wfa.action(
                            action.core.sendNotification,
                            {
                                $id: Now.ID['send_p1_confirmation_notification'],
                                annotation: 'Send P1 task creation confirmation',
                            },
                            {
                                record: `${wfa.dataPill(senderTask.record, 'reference')}`,
                                notification: 'p1_tasks_created_notification',
                            }
                        )
                    }
                )

                // Step 11: Handle internal sender but NOT P1 (create P3 incident)
                wfa.flowLogic.else(
                    {
                        annotation: 'Handle internal sender without P1 priority',
                        $id: Now.ID['handle_internal_non_p1'],
                    },
                    () => {
                        wfa.action(
                            action.core.log,
                            {
                                $id: Now.ID['log_internal_p3_processing'],
                                annotation: 'Log internal non-P1 email processing',
                            },
                            {
                                log_level: 'info',
                                log_message: `Creating P3 incident for internal sender: ${wfa.dataPill(params.trigger.from_address, 'string')}`,
                            }
                        )

                        // Create P3 incident with email information
                        const p3Incident = wfa.action(
                            action.core.createRecord,
                            {
                                $id: Now.ID['create_p3_incident_internal'],
                                annotation: 'Create P3 incident for internal sender',
                            },
                            {
                                table_name: 'incident',
                                values: TemplateValue({
                                    short_description: `${wfa.dataPill(params.trigger.subject, 'string')}`,
                                    description: `${wfa.dataPill(params.trigger.body_text, 'string')}`,
                                    priority: 3,
                                    state: 1,
                                    caller_id: `${wfa.dataPill(params.trigger.from_address, 'string')}`,
                                }),
                            }
                        )

                        // Associate email to incident
                        wfa.action(
                            action.core.associateRecordToEmail,
                            {
                                $id: Now.ID['associate_email_to_p3_incident_internal'],
                                annotation: 'Associate email to P3 incident',
                            },
                            {
                                target_record: `${wfa.dataPill(p3Incident.record, 'reference')}`,
                                email_record: `${wfa.dataPill(params.trigger.inbound_email, 'records')}`,
                            }
                        )

                        // Log successful P3 incident creation
                        wfa.action(
                            action.core.log,
                            {
                                $id: Now.ID['log_p3_incident_created_internal'],
                                annotation: 'Log P3 incident creation for internal sender',
                            },
                            {
                                log_level: 'info',
                                log_message: `P3 incident created: ${wfa.dataPill(p3Incident.record, 'reference')}`,
                            }
                        )

                        // Send confirmation notification
                        wfa.action(
                            action.core.sendNotification,
                            {
                                $id: Now.ID['send_p3_confirmation_internal'],
                                annotation: 'Send P3 incident creation confirmation',
                            },
                            {
                                record: `${wfa.dataPill(p3Incident.record, 'reference')}`,
                                notification: 'p3_incident_created_notification',
                            }
                        )
                    }
                )
            }
        )

        // Step 12: Handle external sender (always create P3 incident)
        wfa.flowLogic.else(
            {
                annotation: 'Handle external sender (non-ServiceNow)',
                $id: Now.ID['handle_external_sender'],
            },
            () => {
                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['log_external_p3_processing'],
                        annotation: 'Log external sender email processing',
                    },
                    {
                        log_level: 'info',
                        log_message: `Creating P3 incident for external sender: ${wfa.dataPill(params.trigger.from_address, 'string')}`,
                    }
                )

                // Create P3 incident with email information
                const p3IncidentExternal = wfa.action(
                    action.core.createRecord,
                    {
                        $id: Now.ID['create_p3_incident_external'],
                        annotation: 'Create P3 incident for external sender',
                    },
                    {
                        table_name: 'incident',
                        values: TemplateValue({
                            short_description: `${wfa.dataPill(params.trigger.subject, 'string')}`,
                            description: `Email from external sender: ${wfa.dataPill(params.trigger.from_address, 'string')}. Body: ${wfa.dataPill(params.trigger.body_text, 'string')}`,
                            priority: 3,
                            state: 1,
                        }),
                    }
                )

                // Associate email to incident
                wfa.action(
                    action.core.associateRecordToEmail,
                    {
                        $id: Now.ID['associate_email_to_p3_incident_external'],
                        annotation: 'Associate email to P3 incident',
                    },
                    {
                        target_record: `${wfa.dataPill(p3IncidentExternal.record, 'reference')}`,
                        email_record: `${wfa.dataPill(params.trigger.inbound_email, 'records')}`,
                    }
                )

                // Log successful P3 incident creation
                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['log_p3_incident_created_external'],
                        annotation: 'Log P3 incident creation for external sender',
                    },
                    {
                        log_level: 'info',
                        log_message: `P3 incident created for external sender: ${wfa.dataPill(p3IncidentExternal.record, 'reference')}`,
                    }
                )

                // Send confirmation notification
                wfa.action(
                    action.core.sendNotification,
                    {
                        $id: Now.ID['send_p3_confirmation_external'],
                        annotation: 'Send P3 incident creation confirmation',
                    },
                    {
                        record: `${wfa.dataPill(p3IncidentExternal.record, 'reference')}`,
                        notification: 'p3_incident_created_notification',
                    }
                )
            }
        )

        // Step 13: Final log of flow completion
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['log_flow_completion'],
                annotation: 'Log flow completion',
            },
            {
                log_level: 'info',
                log_message: `Email processing completed for: ${wfa.dataPill(params.trigger.subject, 'string')}`,
            }
        )
    }
)
